import Foundation
import XCTest
@testable import ChitallCore

/// EPUB fixtures are generated by tools/make_epub_fixtures.py (text written for the tests).
final class EPUBParserTests: XCTestCase {
    private func epub(_ name: String) throws -> ReadableBook {
        try BookImporter.importBook(data: Fixtures.data(name)).book
    }

    private func block(_ book: ReadableBook, _ resource: String, _ path: String) throws -> Block {
        let ordinal = try XCTUnwrap(book.ordinal(of: TextAnchor(resource: resource, path: path)), "\(resource) \(path)")
        return try XCTUnwrap(book.block(ordinal))
    }

    // MARK: EPUB 3

    func testEPUB3Metadata() throws {
        let book = try epub("sample-epub3.epub")
        XCTAssertEqual(book.format, .epub)
        let metadata = book.metadata
        XCTAssertEqual(metadata.title, "Соляная переправа", "the main title, not the subtitle that comes first")
        XCTAssertEqual(metadata.authorLine, "Анна Тестова")
        XCTAssertEqual(metadata.translators.map(\.displayName), ["Пётр Пробный"])
        XCTAssertEqual(metadata.language, "ru")
        XCTAssertEqual(metadata.publisher, "Chitall")
        XCTAssertEqual(metadata.publishYear, "2026")
        XCTAssertEqual(metadata.genres, ["История"])
        XCTAssertEqual(metadata.annotation, "Короткая книга для проверки EPUB.\nТекст написан для тестов & только для них.")
        XCTAssertEqual(metadata.series, BookSeries(name: "Пробные книги", number: "2"))
        XCTAssertEqual(metadata.isbn, "9780000000002")
        XCTAssertEqual(metadata.documentID, "urn:uuid:5b1f0c8e-0000-4000-8000-chitall00003")
        XCTAssertEqual(metadata.coverImageID, "OEBPS/Images/cover.png")
        let cover = try XCTUnwrap(book.images["OEBPS/Images/cover.png"])
        XCTAssertEqual(cover.contentType, "image/png")
        XCTAssertEqual(Array(cover.data.prefix(4)), [0x89, 0x50, 0x4E, 0x47])
    }

    func testEPUB3ChaptersFollowTheSpineAndTheNavigationDocument() throws {
        let book = try epub("sample-epub3.epub")
        XCTAssertEqual(book.chapters.map(\.title), ["Обложка", "Глава первая. Переправа", "Глава вторая. Торг", "Примечания"])
        XCTAssertEqual(book.chapters.map(\.anchor), [
            TextAnchor(resource: "OEBPS/Text/cover.xhtml", path: "/html/body[1]"),
            TextAnchor(resource: "OEBPS/Text/ch1.xhtml", path: "/html/body[1]"),
            TextAnchor(resource: "OEBPS/Text/ch2.xhtml", path: "/html/body[1]"),
            TextAnchor(resource: "OEBPS/Text/notes.xhtml", path: "/html/body[1]"),
        ])
        XCTAssertEqual(book.chapters.map(\.isNotes), [false, false, false, true])
        let market = try block(book, "OEBPS/Text/ch2.xhtml", "/html/body[1]/section[1]/h3[1]")
        let evening = try block(book, "OEBPS/Text/ch2.xhtml", "/html/body[1]/section[2]/h3[1]")
        XCTAssertEqual(book.chapters[2].tableOfContents, [
            TOCEntry(title: "На площади", depth: 1, firstBlock: market.ordinal),
            TOCEntry(title: "Вечер", depth: 1, firstBlock: evening.ordinal),
        ])
        // Ordinals run through the whole book in reading order.
        XCTAssertEqual(book.chapters.flatMap(\.blocks).map(\.ordinal), Array(0..<book.blockCount))
    }

    func testEPUB3BlocksRolesTextAndInlineStyles() throws {
        let book = try epub("sample-epub3.epub")
        let ch1 = "OEBPS/Text/ch1.xhtml"
        let title = try block(book, ch1, "/html/body[1]/section[1]/h1[1]")
        XCTAssertEqual(title.role, .title)
        XCTAssertEqual(title.titleLevel, 1)
        XCTAssertEqual(title.text, "Глава первая\u{2028}Переправа", "<br> is a line break without stray spaces")

        let first = try block(book, ch1, "/html/body[1]/section[1]/p[1]")
        XCTAssertEqual(first.text, "Паром отошёл от берега, когда солнце уже стояло над соляными амбарами.1")
        let styled = first.runs.map { ((first.text as NSString).substring(with: NSRange(location: $0.range.lowerBound, length: $0.range.count)), $0.style) }
        XCTAssertEqual(styled.map(\.0), ["солнце", "соляными", "1"])
        XCTAssertEqual(styled.map(\.1), [.emphasis, .strong, []])
        XCTAssertEqual(first.runs.last?.link, "OEBPS/Text/ch1.xhtml#fn1")
        XCTAssertEqual(first.runs.last?.isNoteReference, true)

        XCTAssertEqual(try block(book, ch1, "/html/body[1]/section[1]/p[2]").text, "Лодочник Ефим молчал и смотрел на\u{00A0}воду.")
        let epigraph = try block(book, ch1, "/html/body[1]/section[1]/blockquote[1]/p[1]")
        XCTAssertTrue(epigraph.context.contains(.epigraph))
        XCTAssertTrue(epigraph.context.contains(.cite))
        let verse = try block(book, ch1, "/html/body[1]/section[1]/div[1]/p[1]")
        XCTAssertEqual(verse.role, .verse)
        XCTAssertEqual(verse.text, "Ой, река моя широкая,\u{2028}переправа далёкая.")
        let link = try block(book, ch1, "/html/body[1]/section[1]/p[3]")
        XCTAssertEqual(link.runs.map(\.link), ["OEBPS/Text/ch2.xhtml#market"])
        XCTAssertEqual(link.runs.map(\.isNoteReference), [false])
        XCTAssertFalse(book.allBlocks.contains { $0.text.contains("Амбары стояли") }, "the footnote aside is shown on tap only")

        let ch2 = "OEBPS/Text/ch2.xhtml"
        XCTAssertEqual(try block(book, ch2, "/html/body[1]/h2[1]").titleLevel, 2)
        XCTAssertEqual(try block(book, ch2, "/html/body[1]/section[1]/h3[1]").titleLevel, 3)
        XCTAssertEqual(try block(book, ch2, "/html/body[1]/section[1]/p[2]").role, .emptyLine, "<p>&#160;</p> is a spacer")
        let stray = try block(book, ch2, "/html/body[1]/section[2]/text()[2]")
        XCTAssertEqual(stray.text, "Свободный текст без абзаца.")
        XCTAssertEqual(try block(book, ch2, "/html/body[1]/section[2]/p[2]").text, "Конец главы.")
    }

    func testEPUB3ImagesNotesAndInternalLinks() throws {
        let book = try epub("sample-epub3.epub")
        let ch2 = "OEBPS/Text/ch2.xhtml"
        let image = try block(book, ch2, "/html/body[1]/section[1]/figure[1]/img[1]")
        XCTAssertEqual(image.role, .image)
        XCTAssertEqual(image.imageID, "OEBPS/Images/map.png")
        XCTAssertNotNil(book.images["OEBPS/Images/map.png"])
        XCTAssertEqual(try block(book, ch2, "/html/body[1]/section[1]/figure[1]/figcaption[1]").text, "Карта торговой площади")
        XCTAssertEqual(book.chapters[0].blocks.map(\.imageID), ["OEBPS/Images/cover.png"])

        let footnote = try XCTUnwrap(book.notes["OEBPS/Text/ch1.xhtml#fn1"])
        XCTAssertEqual(footnote.title, "1")
        XCTAssertEqual(footnote.text, "Амбары стояли у самой пристани.")
        let endnote = try XCTUnwrap(book.notes["OEBPS/Text/notes.xhtml#en1"])
        XCTAssertEqual(endnote.title, "2")
        XCTAssertEqual(endnote.text, "Цена соли менялась каждую неделю.", "the ↩ back link is not part of the note")
        XCTAssertEqual(book.notes.count, 2)

        XCTAssertEqual(book.idTargets["OEBPS/Text/ch2.xhtml#market"], try block(book, ch2, "/html/body[1]/section[1]/h3[1]").ordinal)
        XCTAssertEqual(book.idTargets["OEBPS/Text/ch2.xhtml"], book.chapters[2].firstBlock)
    }

    // MARK: EPUB 2

    func testEPUB2WithNCXEntitiesAndCalibreNotes() throws {
        let book = try epub("sample-epub2.epub")
        let metadata = book.metadata
        XCTAssertEqual(metadata.title, "Зимний обоз")
        XCTAssertEqual(metadata.authorLine, "Анна Тестова", "the illustrator is not an author")
        XCTAssertEqual(metadata.series, BookSeries(name: "Пробные книги", number: "3"))
        XCTAssertEqual(metadata.isbn, "9780000000019")
        XCTAssertEqual(metadata.annotation, "Вторая пробная книга.")
        XCTAssertEqual(metadata.coverImageID, "Images/winter.png")
        XCTAssertNotNil(book.images["Images/winter.png"])

        XCTAssertEqual(book.chapters.map(\.title), ["Часть первая", "Примечания"])
        let part = "Text/part 1.html"
        XCTAssertEqual(book.chapters[0].anchor.resource, part, "percent-encoded hrefs point at the real file name")
        let road = try block(book, part, "/html/body[1]/div[1]/h2[1]")
        XCTAssertEqual(book.chapters[0].tableOfContents, [TOCEntry(title: "Обоз в пути", depth: 1, firstBlock: road.ordinal)])

        XCTAssertEqual(try block(book, part, "/html/body[1]/div[1]/div[1]").text, "Мороз стоял такой, что\u{00A0}полозья пели.")
        let question = try block(book, part, "/html/body[1]/div[1]/p[1]")
        XCTAssertEqual(question.text, "«Доедем ли?» — спросил мальчик.[1]", "XHTML 1.1 entities without the DTD")
        XCTAssertEqual(question.runs.last?.link, "Text/notes.html#n1")
        XCTAssertEqual(question.runs.last?.isNoteReference, true)
        XCTAssertEqual(try block(book, part, "/html/body[1]/div[1]/p[2]").role, .emptyLine)
        let forest = try block(book, part, "/html/body[1]/div[1]/p[3]")
        XCTAssertEqual(forest.text, "Дорога шла лесом, и волки выли…")
        XCTAssertEqual(forest.runs.map(\.style), [.emphasis, .strong], "inline style=\"font-style: italic\" and <b>")
        XCTAssertEqual(try block(book, part, "/html/body[1]/div[1]/text()[7]").text, "Текст прямо в разделе.")
        let night = try block(book, part, "/html/body[1]/div[1]/p[4]")
        XCTAssertEqual(night.text, "Ночевали в\u{00A0}деревне у старосты.2")
        XCTAssertEqual(night.runs.map(\.link), ["Text/notes.html#n2"], "external links are dropped (offline app)")

        XCTAssertEqual(book.notes["Text/notes.html#n1"]?.text, "[1] Обоз шёл\u{00A0}три дня.")
        XCTAssertEqual(book.notes["Text/notes.html#n1"]?.title, "1")
        XCTAssertEqual(book.notes["Text/notes.html#n2"]?.text, "2 Староста брал за ночлег соль.")
        XCTAssertEqual(Set(book.notes.keys), ["Text/notes.html#n1", "Text/notes.html#n2"], "back links are not notes")
        let back = try block(book, "Text/notes.html", "/html/body[1]/p[1]")
        XCTAssertEqual(back.runs.first?.link, "Text/part 1.html#r1")
        XCTAssertEqual(back.runs.first?.isNoteReference, false, "a back link jumps to the text")
        XCTAssertEqual(book.idTargets["Text/part 1.html#r1"], question.ordinal)
    }

    // MARK: Import, fingerprint, errors

    func testImportKeepsTheWholeEPUBAndReopensTheSameBook() throws {
        let data = try Fixtures.data("sample-epub3.epub")
        let imported = try BookImporter.importBook(data: data)
        XCTAssertEqual(imported.format, .epub)
        XCTAssertEqual(imported.sourceData, data)
        XCTAssertEqual(imported.fingerprint, "sha256:" + PortableSHA256.hash(data).map { String(format: "%02x", $0) }.joined())
        XCTAssertNil(imported.archiveEntryName)
        let reopened = try BookImporter.readStoredBook(imported.sourceData)
        XCTAssertEqual(reopened.allBlocks, imported.book.allBlocks)
        XCTAssertEqual(reopened.format, .epub)
        // FB2 still opens through the same entry point.
        XCTAssertEqual(try BookImporter.readStoredBook(Fixtures.data("sample-utf8.fb2")).format, .fb2)
    }

    func testDRMProtectedEPUBIsRefusedWithAClearMessage() throws {
        XCTAssertThrowsImportError(try BookImporter.importBook(data: Fixtures.data("drm.epub")), .drmProtected)
        XCTAssertTrue(BookImportError.drmProtected.userMessage.contains("DRM"))
        XCTAssertTrue(BookImportError.drmProtected.userMessage.contains("без защиты"))
        // Font obfuscation is not DRM: the book reads normally.
        let fonts = try BookImporter.importBook(data: Fixtures.data("obfuscated-fonts.epub"))
        XCTAssertEqual(fonts.book.chapters.count, 4)
    }

    func testBrokenEPUBsExplainWhatIsWrong() throws {
        XCTAssertThrowsError(try BookImporter.importBook(data: Fixtures.data("broken-xhtml.epub"))) { error in
            guard case let .damagedEPUB(reason) = error as? BookImportError else { return XCTFail("got \(error)") }
            XCTAssertTrue(reason.contains("OEBPS/Text/ch2.xhtml"), reason)
            XCTAssertTrue((error as? BookImportError)?.userMessage.hasPrefix("Файл EPUB повреждён: ошибка XML") ?? false)
        }
        XCTAssertThrowsImportError(
            try BookImporter.importBook(data: Fixtures.data("no-container.epub")),
            .damagedEPUB("нет файла META-INF/container.xml")
        )
        XCTAssertEqual(BookImportError.archiveWithoutFB2.userMessage, "В архиве нет книги: ни файла .fb2, ни EPUB.")
    }

    // MARK: Locators

    func testLocatorInEPUBNamesTheResourceAndSurvivesRepackingAndEdits() throws {
        let data = try Fixtures.data("sample-epub3.epub")
        let book = try BookImporter.importBook(data: data).book
        let service = LocatorService(book: book, fingerprint: Fingerprint.of(data))
        let paragraph = try block(book, "OEBPS/Text/ch1.xhtml", "/html/body[1]/section[1]/p[2]")
        let range = BlockRange(start: BlockPosition(block: paragraph.ordinal, offset: 9), end: BlockPosition(block: paragraph.ordinal, offset: 20))
        let locator = try XCTUnwrap(service.locator(for: range))
        XCTAssertEqual(locator.format, .epub)
        XCTAssertEqual(locator.chapter, 1)
        XCTAssertEqual(locator.start, Locator.Point(resource: "OEBPS/Text/ch1.xhtml", path: "/html/body[1]/section[1]/p[2]", offset: 9))
        XCTAssertEqual(locator.end?.offset, 20)
        XCTAssertEqual(locator.quote?.exact, "Ефим молчал")
        let json = try locator.jsonString()
        XCTAssertTrue(json.contains(#""format":"epub""#), json)
        XCTAssertTrue(json.contains(#""resource":"OEBPS/Text/ch1.xhtml""#), json)
        XCTAssertEqual(service.resolve(try Locator.fromJSONString(json)), .exact(range))

        // The same book packed differently: other bytes, same paths.
        let stored = try BookImporter.importBook(data: Fixtures.data("sample-epub3-stored.epub"))
        XCTAssertNotEqual(stored.fingerprint, Fingerprint.of(data))
        XCTAssertEqual(LocatorService(book: stored.book, fingerprint: stored.fingerprint).resolve(locator), .exact(range))

        // A paragraph inserted before: the quote finds the text at its new path.
        let edited = try BookImporter.importBook(data: Fixtures.data("sample-epub3-edited.epub")).book
        let moved = try block(edited, "OEBPS/Text/ch1.xhtml", "/html/body[1]/section[1]/p[3]")
        XCTAssertEqual(
            LocatorService(book: edited, fingerprint: "sha256:other").resolve(locator),
            .relocated(BlockRange(start: BlockPosition(block: moved.ordinal, offset: 9), end: BlockPosition(block: moved.ordinal, offset: 20)))
        )
    }

    func testReadingPositionChapterTextAndSearchWorkUnchanged() throws {
        let data = try Fixtures.data("sample-epub3.epub")
        let book = try BookImporter.importBook(data: data).book
        let service = LocatorService(book: book, fingerprint: Fingerprint.of(data))
        let stray = try block(book, "OEBPS/Text/ch2.xhtml", "/html/body[1]/section[2]/text()[2]")
        let caret = try XCTUnwrap(service.locator(at: BlockPosition(block: stray.ordinal, offset: 4)))
        XCTAssertNil(caret.end)
        XCTAssertEqual(service.resolve(caret), .caret(BlockPosition(block: stray.ordinal, offset: 4)))

        let text = ChapterText(chapter: book.chapters[1])
        let title = try block(book, "OEBPS/Text/ch1.xhtml", "/html/body[1]/section[1]/h1[1]")
        XCTAssertTrue(text.string.hasPrefix("Глава первая\u{2028}Переправа\n"))
        let afterBreak = BlockPosition(block: title.ordinal, offset: 13)
        XCTAssertEqual(text.position(atUTF16: try XCTUnwrap(text.utf16Offset(of: afterBreak)), forward: true), afterBreak)

        let cover = ChapterText(chapter: book.chapters[0])
        XCTAssertEqual(cover.string, ChapterText.attachmentCharacter)

        let result = BookSearch.search("пересчитал", in: book)
        XCTAssertEqual(result.hits.map(\.chapterIndex), [2])
        XCTAssertEqual(result.hits.first.map { book.text(in: $0.range) }, "пересчитал")
    }

    // MARK: Canonical text

    func testLineBreaksAreKeptOnlyForEPUB() {
        let segments: [TextCanonicalizer.Segment] = [.init(text: "  Ой, река \u{2028}\n  широкая "), .init(text: "\u{2028}", style: .emphasis)]
        XCTAssertEqual(TextCanonicalizer.canonicalize(segments, keepsLineBreaks: true).text, "Ой, река\u{2028}широкая")
        XCTAssertEqual(TextCanonicalizer.canonicalize(segments).text, "Ой, река \u{2028} широкая \u{2028}", "FB2 rules unchanged")
        XCTAssertEqual(TextCanonicalizer.canonicalize([.init(text: "\u{2028}a\u{2028}\u{2028}b")], keepsLineBreaks: true).text, "a\u{2028}\u{2028}b")
    }

    func testHTMLEntitiesBecomeCharacterReferences() {
        let rewritten = HTMLEntityRewriter.rewrite(Data("<p>a&nbsp;b &amp; &mdash; &unknown; &#171;</p>".utf8))
        XCTAssertEqual(String(decoding: rewritten, as: UTF8.self), "<p>a&#xa0;b &amp; &#x2014; &amp;unknown; &#171;</p>")
        XCTAssertEqual(HTMLText.plain("<p>Раз&nbsp;два</p><p>три &amp; четыре</p>"), "Раз\u{00A0}два\nтри & четыре")
    }

    func testRelativeHrefsResolveInsideTheContainer() {
        XCTAssertEqual(EPUBPath.resolve("../Images/a%20b.png", relativeTo: "OEBPS/Text/ch1.xhtml"), "OEBPS/Images/a b.png")
        XCTAssertEqual(EPUBPath.resolve("./ch2.xhtml", relativeTo: "OEBPS/Text/ch1.xhtml"), "OEBPS/Text/ch2.xhtml")
        XCTAssertEqual(EPUBPath.resolve("/OEBPS/x.xhtml", relativeTo: "a/b.xhtml"), "OEBPS/x.xhtml")
        let resolver = EPUBLinkResolver(resource: "OEBPS/Text/ch1.xhtml")
        XCTAssertEqual(resolver.target("#n1"), "OEBPS/Text/ch1.xhtml#n1")
        XCTAssertEqual(resolver.target("notes.xhtml#n%201"), "OEBPS/Text/notes.xhtml#n 1")
        XCTAssertNil(resolver.target("https://example.com/"))
        XCTAssertNil(resolver.target("mailto:a@b.c"))
    }
}

final class InflateTests: XCTestCase {
    func testPortableInflateDecodesStoredFixedAndDynamicBlocks() throws {
        let original = try Fixtures.data("sample-utf8.fb2")
        for name in ["stored", "fixed", "dynamic"] {
            let compressed = try Fixtures.data("inflate/\(name).deflate")
            XCTAssertEqual(try PortableInflate.inflate(compressed), original, name)
            XCTAssertEqual(try ZipArchive.portableInflater(compressed, original.count), original, name)
            if let system = ZipArchive.systemInflater {
                XCTAssertEqual(try system(compressed, original.count), original, "\(name): Compression and the portable decoder agree")
            }
        }
    }

    func testPortableInflateRejectsDamagedStreams() throws {
        let compressed = try Fixtures.data("inflate/dynamic.deflate")
        XCTAssertThrowsError(try PortableInflate.inflate(compressed.prefix(compressed.count / 2)))
        XCTAssertThrowsError(try PortableInflate.inflate(Data([0xFF, 0xFF])))
        XCTAssertThrowsError(try PortableInflate.inflate(compressed, limit: 100)) { error in
            XCTAssertEqual(error as? PortableInflate.Failure, .outputTooLarge)
        }
    }
}
